use std::fs

fn best(prios: Vec<int>) -> int {
    let mut b = 0
    let n: int = prios.len() as int
    let mut i = 1
    while i < n {
        if prios[i as usize] > prios[b as usize] {
            b = i
        }
        i += 1
    }
    b
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = []
    let mut prios: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        let n: int = parts.len() as int
        if n == 0 {
            println("error")
            continue
        }
        let cmd = parts[0].clone()
        if cmd == "add" && n == 3 {
            match parts[2].parse::<int>() {
                Ok(p) => {
                    names.push(parts[1].clone())
                    prios.push(p)
                }
                Err(_) => println("error")
            }
        } else if cmd == "pop" && n == 1 {
            if names.len() == 0 {
                println("empty")
            } else {
                let b = best(prios.clone()) as usize
                println(names[b])
                names.remove(b)
                prios.remove(b)
            }
        } else if cmd == "peek" && n == 1 {
            if names.len() == 0 {
                println("empty")
            } else {
                let b = best(prios.clone()) as usize
                println(names[b])
            }
        } else if cmd == "size" && n == 1 {
            println("${names.len()}")
        } else {
            println("error")
        }
    }
    println("left:")
    while names.len() > 0 {
        let b = best(prios.clone()) as usize
        println("${names[b]} ${prios[b]}")
        names.remove(b)
        prios.remove(b)
    }
}

